ets.","start_date":"01/01/2021","end_date":"31/12/2021","feder_operation_cost":197950.82,"eu_cofinancing_percent":50.0,"province":"Zaragoza","municipality":"Alfajarín","municipality_code":"50017","intervention":"001 Inversión productiva genérica en pequeñas y medianas –empresas («PYME»)","source_url":"https://www.dgfc.sepg.hacienda.gob.es/sitios/dgfc/es-ES/loFEDER1420/porFEDER/Documents/LO-AR.pdf#page=349","source_file":"feder-aragon-2014-2020-20250529.pdf","source_page":349,"source_updated":"2025-05-29"},{"operation_code":"D2021084","year":2021,"line":"IDIS-REACT","beneficiary":"ZFOAM ESPAÑA, S.L.","feder_beneficiary_id":"ES59C779","operation_name":"ZFOAM ESPAÑA, S.L.","description":"\"ZFOAM tiene como objetivo tener una fábrica inteligente, por ello todos los años lleva a cabo una serie de inversiones para dotar a su planta de la tecnología más puntera del mercado y contratar los servicios de consultoría que le ayude a esta transformación. Por ello ha llevado a cabo Inversiones en Transformación Digital, Inversiones en equipos y acondicionamientos a la digitalización e instalaciones de incendios y nueva planta productiva\"","start_date":"01/02/2020","end_date":"31/07/2021","feder_operation_cost":63777.0,"eu_cofinancing_percent":100.0,"province":"Zaragoza","municipality":"Alfajarín","municipality_code":"50017","intervention":"004 Inversión productiva relativas a la cooperación entre grandes empresas y PYME para desarrollar productos y servicios en tecnologías de la información y las comunicaciones (TIC), comercio electrónico y mayor demanda de TIC.","source_url":"https://www.dgfc.sepg.hacienda.gob.es/sitios/dgfc/es-ES/loFEDER1420/porFEDER/Documents/LO-AR.pdf#page=509","source_file":"feder-aragon-2014-2020-20250529.pdf","source_page":509,"source_updated":"2025-05-29"},{"operation_code":"AR_OP000242","project_code":"TDI2023199_M_P250","year":2023,"line":"TDI-FEDER","beneficiary":"ZFOAM ESPAÑA, S.L.","feder_beneficiary_id":"ES59C0000779","nif":"B50525187","operation_n